// Sprite frames. Real art comes from BM.SPRITE_FILES (generated by tools/build_manifests.mjs from
// sheets sliced by tools/slice_sheet.py). Anything without art gets a procedural placeholder so the
// game is always playable. All frames face RIGHT; the renderer flips enemies.
window.BM = window.BM || {};
BM.SPRITE_FILES = BM.SPRITE_FILES || {};
BM.BG_FILES = BM.BG_FILES || {};
BM.FX_FILES = BM.FX_FILES || {};
BM.ART = BM.ART || {};
BM.Sprites = (function () {
  const cache = {};   // formId -> { run:[img/canvas], attack:[...], w, h, ax, ay, placeholder }
  const images = {};  // src -> HTMLImageElement
  const bgs = {};     // key -> image
  const arts = {};    // 'bases/player_base' | 'ui/logo' | 'icons/type_fire' ... -> image
  const fxs = {};     // type -> { frames:[canvas x3], w, h, ax, ay }  (in flight, full size, impact)

  function loadImage(src) {
    if (images[src]) return images[src];
    const p = new Promise((res) => { const im = new Image(); im.onload = () => res(im); im.onerror = () => res(null); im.src = src; });
    images[src] = p;
    return p;
  }
  function cut(im, meta, idx) {
    const c = document.createElement('canvas');
    c.width = meta.cellW; c.height = meta.cellH;
    c.getContext('2d').drawImage(im, idx * meta.cellW, 0, meta.cellW, meta.cellH, 0, 0, meta.cellW, meta.cellH);
    return c;
  }
  async function loadAll() {
    const jobs = Object.entries(BM.SPRITE_FILES).map(async ([key, def]) => {
      const out = { run: [], attack: [] };
      for (const part of ['run', 'attack']) {
        const sh = def[part];
        if (!sh) continue;
        const im = await loadImage(sh.src);
        if (!im) continue;
        out[part] = sh.frames.map((i) => cut(im, sh, i));
        out.w = sh.cellW; out.h = sh.cellH; out.ax = sh.anchorX; out.ay = sh.anchorY;
      }
      if (out.run.length) {
        if (!out.attack.length) out.attack = [out.run[0]]; // run-only sheets: lunge + effect sprite
        cache['art:' + key] = out;
      }
    });
    const fxJobs = Object.entries(BM.FX_FILES).map(async ([type, sh]) => {
      const im = await loadImage(sh.src);
      if (im) fxs[type] = { frames: sh.frames.map((i) => cut(im, sh, i)), w: sh.cellW, h: sh.cellH, ax: sh.anchorX, ay: sh.anchorY };
    });
    const bgJobs = Object.entries(BM.BG_FILES).map(async ([key, src]) => { const im = await loadImage(src); if (im) bgs[key] = im; });
    const artJobs = Object.entries(BM.ART).map(async ([key, src]) => { const im = await loadImage(src); if (im) arts[key] = im; });
    await Promise.all([...jobs, ...fxJobs, ...bgJobs, ...artJobs]);
  }

  function shade(hex, f) {
    const n = parseInt(hex.slice(1), 16);
    const ch = (v) => Math.max(0, Math.min(255, Math.round(v * f)));
    return `rgb(${ch(n >> 16)},${ch((n >> 8) & 255)},${ch(n & 255)})`;
  }
  // Placeholder: chunky type-coloured critter, 4 run frames + wind-up + strike.
  function placeholder(form) {
    const H = 128, W = 128;
    const c1 = BM.TYPE_COLORS[form.types[0]], c2 = BM.TYPE_COLORS[form.types[1] || form.types[0]];
    const mk = (pose) => {
      const c = document.createElement('canvas'); c.width = W; c.height = H + 2;
      const g = c.getContext('2d');
      g.lineWidth = 5; g.strokeStyle = '#1c1c28'; g.lineJoin = 'round';
      const lean = pose === 'windup' ? -8 : pose === 'strike' ? 10 : 0;
      const crouch = pose === 'windup' ? 8 : 0;
      const bob = typeof pose === 'number' ? [0, -4, 0, -2][pose] : 0;
      const legA = typeof pose === 'number' ? [12, 0, -12, 0][pose] : 0;
      // feet
      g.fillStyle = shade(c1, 0.7);
      for (const dx of [-14 + legA, 14 - legA]) {
        g.beginPath(); g.ellipse(64 + dx + lean / 2, H - 8, 12, 7, 0, 0, Math.PI * 2); g.fill(); g.stroke();
      }
      // tail
      g.fillStyle = c2;
      g.beginPath(); g.moveTo(30 + lean, 78 + crouch + bob); g.lineTo(6 + lean, 52 + bob); g.lineTo(26 + lean, 92 + crouch + bob); g.closePath(); g.fill(); g.stroke();
      // body
      g.fillStyle = c1;
      g.beginPath(); g.ellipse(64 + lean, 80 + crouch + bob, 36, 34 - crouch / 2, 0, 0, Math.PI * 2); g.fill(); g.stroke();
      // belly in second type colour
      g.fillStyle = shade(c2, 1.15);
      g.beginPath(); g.ellipse(74 + lean, 90 + crouch + bob, 18, 16, 0, 0, Math.PI * 2); g.fill();
      // ears
      g.fillStyle = shade(c1, 0.85);
      for (const ex of [52, 72]) {
        g.beginPath(); g.moveTo(ex + lean, 52 + crouch + bob); g.lineTo(ex + 6 + lean, 30 + crouch + bob); g.lineTo(ex + 14 + lean, 50 + crouch + bob); g.closePath(); g.fill(); g.stroke();
      }
      // eye (facing right)
      g.fillStyle = '#fff'; g.beginPath(); g.arc(82 + lean, 70 + crouch + bob, 8, 0, Math.PI * 2); g.fill(); g.lineWidth = 3; g.stroke();
      g.fillStyle = '#1c1c28'; g.beginPath(); g.arc(85 + lean, 70 + crouch + bob, 4, 0, Math.PI * 2); g.fill();
      if (pose === 'strike') { g.fillStyle = '#1c1c28'; g.beginPath(); g.arc(96 + lean, 84 + bob, 5, 0, Math.PI * 2); g.fill(); }
      return c;
    };
    const run = [mk(0), mk(1), mk(2), mk(3)];
    // wave fodder is run-sheet-only (§4.10): its attack is a lunge, same as when its real art lands
    const attack = form.runOnly ? [run[0]] : [mk('windup'), mk('strike')];
    return { run, attack, w: W, h: H + 2, ax: W / 2, ay: H, placeholder: true };
  }
  function get(form) {
    const k = form.sprite || form.id;
    if (cache['art:' + k]) return cache['art:' + k];
    if (!cache['ph:' + form.id]) cache['ph:' + form.id] = placeholder(form);
    return cache['ph:' + form.id];
  }
  function bg(key) { return bgs[key] || null; }
  function fx(type) { return fxs[type] || null; }
  function art(key) { return arts[key] || null; }
  function artSrc(key) { return arts[key] ? arts[key].src : null; }
  // true when a form's real art is wired (both sheets, or the run sheet for run-only fodder)
  function hasArt(form) { return !!cache['art:' + (form.sprite || form.id)]; }
  return { loadAll, get, bg, fx, art, artSrc, hasArt };
})();
